package kome.common.data;
import lotr.common.LOTRPlayerData;import lotr.common.entity.npc.LOTREntityNPC;import lotr.common.quest.LOTRMiniQuest;import net.minecraft.init.Items;import net.minecraft.item.ItemStack;import net.minecraft.nbt.NBTTagCompound;
/** Native presentation shell for a canonical prospective-Liege sponsorship. */
public final class KOMELiegeOfferQuest extends LOTRMiniQuest { public static final String TYPE="KOMELiegeOffer";private long window;private String story="";public KOMELiegeOfferQuest(LOTRPlayerData d){super(d);}private KOMELiegeOfferQuest(LOTRPlayerData d,LOTREntityNPC n,long w,String s,LOTRMiniQuest template){super(d);window=w;story=s==null?"":s;copyNativePresentation(template);setNPCInfo(n);quoteStart=story;}public static KOMELiegeOfferQuest create(LOTRPlayerData d,LOTREntityNPC n,long w,String s){if(n==null||s==null||s.trim().length()==0)return null;LOTRMiniQuest template=n.createMiniQuest();if(!hasNativePresentation(template))return null;return new KOMELiegeOfferQuest(d,n,w,s,template);}private void copyNativePresentation(LOTRMiniQuest q){questGroup=q.questGroup;speechBankStart=q.speechBankStart;speechBankProgress=q.speechBankProgress;speechBankComplete=q.speechBankComplete;speechBankTooMany=q.speechBankTooMany;quoteComplete=q.quoteComplete;quotesStages.addAll(q.quotesStages);}private static boolean hasNativePresentation(LOTRMiniQuest q){return q!=null&&q.questGroup!=null&&nonEmpty(q.speechBankStart)&&nonEmpty(q.speechBankProgress)&&nonEmpty(q.speechBankComplete)&&nonEmpty(q.speechBankTooMany)&&nonEmpty(q.quoteStart)&&nonEmpty(q.quoteComplete);}private static boolean nonEmpty(String s){return s!=null&&s.length()!=0;}public boolean expired(long w){return window!=w;}public String getQuestObjective(){return "Seek knighthood in the service of "+entityNameFull;}public String getObjectiveInSpeech(){return "enter my service";}public String getProgressedObjectiveInSpeech(){return getObjectiveInSpeech();}public String getQuestProgress(){return "Sponsorship offer";}public String getQuestProgressShorthand(){return "Sponsorship";}public float getCompletionFactor(){return 0;}public ItemStack getQuestIcon(){return new ItemStack(Items.iron_sword);}public float getAlignmentBonus(){return 0;}public int getCoinBonus(){return 0;}public void writeToNBT(NBTTagCompound t){super.writeToNBT(t);t.setLong("KOMEWindow",window);t.setString("KOMEStory",story);}public void readFromNBT(NBTTagCompound t){super.readFromNBT(t);window=t.getLong("KOMEWindow");story=t.getString("KOMEStory");quoteStart=story;} }
